 var list=el('chainToolsList');if(!list)return;list.innerHTML='';var items=visibleItems(),visibleEntries=items.filter(function(item){return item.kind==='entry'}),selectedVisible=visibleEntries.filter(function(item){return !!tool.selected[item.index]}),selectAll=el('chainToolSelectAll');if(selectAll){selectAll.disabled=!visibleEntries.length;selectAll.checked=!!visibleEntries.length&&selectedVisible.length===visibleEntries.length;selectAll.indeterminate=selectedVisible.length>0&&selectedVisible.length<visibleEntries.length}if(!items.length){var empty=document.createElement('div');empty.className='chain-tools-empty';empty.textContent='暂无匹配行；可先导入或刷新自定义优选';list.appendChild(empty);return}
