function syncText(shouldMark){if(!tool||!tool.textarea)return;tool.textarea.value=tool.lines.join('\n');lastTextareaValue=tool.textarea.value;if(typeof tool.textarea._refreshLineEditor==='function')tool.textarea._refreshLineEditor();tool.textarea.dispatchEvent(new Event('input',{bubbles:true}));if(shouldMark)mark();migrateMeta();render();persistLocal()}
