function parseImport(text){var value=String(text||'').replace(/^\uFEFF/,'');var obfuscatedParts=value.split(/\r?\n/);if(String(obfuscatedParts[0]||'').trim()==='EDGE_CHAIN_OBFUSCATED_V1'){var expected=obfuscatedParts[1]||'',decoded=unmaskText(obfuscatedParts.slice(2).join(''),String(el('chainToolMaskKey')&&el('chainToolMaskKey').value||tool.maskKey||'edge-tunnel-chain-v1'));if(expected&&checksum(decoded)!==expected)throw new Error('混淆文件校验值不匹配');return decoded}if(value.trim().charAt(0)==='{'||value.trim().charAt(0)==='['){var json=JSON.parse(value);if(Array.isArray(json))return json.join('\n');if(typeof json.text==='string')return json.text;if(Array.isArray(json.entries))return json.entries.join('\n')}return value}
function importText(text,mode){var incoming=parseImport(text),old=entryText();if(mode==='merge'){var existing={};tool.lines.forEach(function(raw,i){var item=parseLine(raw,i);if(item.kind==='entry')existing[nodeKey(item)]=true});incoming.split(/\r?\n/).forEach(function(raw){var item=parseLine(raw,0);if(item.kind==='entry'&&!existing[nodeKey(item)]){tool.lines.push(raw);existing[nodeKey(item)]=true}})}else tool.lines=incoming.split(/\r?\n/);syncText(true);toast(mode==='merge'?'已合并导入节点':'已替换为导入内容','success')}
