	function loadSources(){var area=el('chainToolSources');if(area)area.value=(tool.sources||[]).join('\n')}
	function updateNetworkToolButtons(){var enabled=!!(tool&&tool.networkToolsEnabled),ids=['chainToolRefresh','chainToolProbe'];ids.forEach(function(id){var button=el(id);if(!button)return;button.disabled=!enabled;button.title=enabled?'已启用受控网络工具':'需要部署变量 CHAIN_NETWORK_TOOLS=1，并配置对应主机白名单'})}
	function readSources(){var area=el('chainToolSources');tool.sources=String(area&&area.value||'').split(/\r?\n/).map(function(x){return x.trim()}).filter(Boolean).slice(0,16);persistLocal()}
function mergeSourceText(text){var incoming='';try{var parsed=JSON.parse(text);if(Array.isArray(parsed))incoming=parsed.join('\n');else if(parsed&&Array.isArray(parsed.data))incoming=parsed.data.join('\n');else if(parsed&&typeof parsed.text==='string')incoming=parsed.text}catch(error){incoming=text}var existing={};tool.lines.forEach(function(raw,i){var item=parseLine(raw,i);if(item.kind==='entry')existing[nodeKey(item)]=true});incoming.split(/\r?\n/).forEach(function(raw){var item=parseLine(raw,0);if(item.kind==='entry'&&!existing[nodeKey(item)]){tool.lines.push(raw);existing[nodeKey(item)]=true}})}
	async function refreshSources(){readSources();if(!tool.networkToolsEnabled){toast('来源刷新需要部署变量 CHAIN_NETWORK_TOOLS=1','info');return}if(!tool.sources.length){toast('请先填写至少一个来源地址','error');return}var button=el('chainToolRefresh');if(button)button.disabled=true;try{var response=await fetch('/admin/chain/fetch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({urls:tool.sources.slice(0,2)})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'来源刷新失败');var added=0;data.results.forEach(function(result){if(result.ok){var before=tool.lines.length;mergeSourceText(result.text);added+=tool.lines.length-before}});syncText(true);var failures=data.results.filter(function(x){return !x.ok});toast('来源刷新完成，新增 '+added+' 行'+(failures.length?'，失败 '+failures.length+' 个':''),failures.length?'info':'success');}catch(error){toast('来源刷新失败: '+error.message,'error')}finally{if(button)button.disabled=!tool.networkToolsEnabled}}
	function applyAutoRefresh(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=null;var enabled=!!tool.settings.refreshEnabled,minutes=Math.max(5,Number(tool.settings.refreshMinutes)||60);if(enabled&&tool.networkToolsEnabled)refreshTimer=setInterval(refreshSources,minutes*60*1000)}
function saveSettings(){tool.settings.refreshEnabled=!!(el('chainToolAutoRefresh')&&el('chainToolAutoRefresh').checked);tool.settings.refreshMinutes=Number(el('chainToolRefreshMinutes')&&el('chainToolRefreshMinutes').value)||60;tool.maskKey=String(el('chainToolMaskKey')&&el('chainToolMaskKey').value||'edge-tunnel-chain-v1');persistLocal();applyAutoRefresh()}
async function saveWorkspace(silent){readSources();saveSettings();try{var response=await fetch('/admin/chain/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:entryText(),sources:tool.sources,settings:tool.settings,meta:tool.meta})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'工作区保存失败');loadAudit();if(!silent)toast('工作区已保存','success')}catch(error){if(!silent)toast('工作区保存失败: '+error.message,'error')}}
async function loadWorkspace(){try{var local=loadLocal();tool.sources=Array.isArray(local.sources)?local.sources:[];tool.settings=Object.assign(tool.settings,local.settings||{});tool.meta=local.meta&&typeof local.meta==='object'?local.meta:{};tool.maskKey=String(local.maskKey||tool.maskKey);tool.networkToolsEnabled=false;var response=await fetch('/admin/chain/state?_t='+Date.now(),{cache:'no-store'}),data=await response.json();tool.networkToolsEnabled=!!(response.ok&&data&&data.networkToolsEnabled);if(response.ok&&data&&data.version){if(Array.isArray(data.sources)&&data.sources.length)tool.sources=data.sources;tool.settings=Object.assign(tool.settings,data.settings||{});tool.meta=Object.assign(tool.meta,data.meta||{});if(!String(tool.textarea.value||'').trim()&&String(data.text||'').trim())tool.textarea.value=data.text;lastTextareaValue=null;reloadLines(true);persistLocal()}loadSources();if(el('chainToolAutoRefresh'))el('chainToolAutoRefresh').checked=!!tool.settings.refreshEnabled;if(el('chainToolRefreshMinutes'))el('chainToolRefreshMinutes').value=String(tool.settings.refreshMinutes||60);if(el('chainToolMaskKey'))el('chainToolMaskKey').value=tool.maskKey;updateNetworkToolButtons();applyAutoRefresh();render()}catch(error){tool.networkToolsEnabled=false;loadSources();if(el('chainToolAutoRefresh'))el('chainToolAutoRefresh').checked=!!tool.settings.refreshEnabled;if(el('chainToolRefreshMinutes'))el('chainToolRefreshMinutes').value=String(tool.settings.refreshMinutes||60);if(el('chainToolMaskKey'))el('chainToolMaskKey').value=tool.maskKey;updateNetworkToolButtons();applyAutoRefresh()}}
async function loadBackups(){try{var response=await fetch('/admin/chain/backups?_t='+Date.now(),{cache:'no-store'}),data=await response.json(),select=el('chainToolBackupSelect');if(!select)return;select.innerHTML='<option value="">选择备份</option>';(data.backups||[]).forEach(function(item){var option=document.createElement('option');option.value=item.id;option.textContent=item.name+' · '+new Date(item.createdAt).toLocaleString()+' · '+item.entryCount+'行';select.appendChild(option)})}catch(error){}}
async function loadAudit(){try{var response=await fetch('/admin/chain/audit?_t='+Date.now(),{cache:'no-store'}),data=await response.json(),target=el('chainToolAuditList');if(!target)return;target.textContent=(data.audit||[]).slice(0,5).map(function(item){return new Date(item.time).toLocaleString()+' · '+item.action+' · '+JSON.stringify(item.details||{})}).join('\n')||'暂无工具箱操作日志'}catch(error){}}
async function createBackup(){var name=prompt('备份名称',new Date().toLocaleString('zh-CN',{hour12:false}));if(name===null)return;try{var response=await fetch('/admin/chain/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',name:name,state:{text:entryText(),sources:tool.sources,settings:tool.settings,meta:tool.meta}})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'备份失败');await loadBackups();loadAudit();toast('备份已创建','success')}catch(error){toast('备份失败: '+error.message,'error')}}
async function restoreBackup(){var select=el('chainToolBackupSelect'),id=select&&select.value;if(!id){toast('请先选择备份','error');return}if(!confirm('确认恢复所选备份？当前未保存内容会被替换。'))return;try{var response=await fetch('/admin/chain/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'restore',id:id})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'恢复失败');tool.textarea.value=data.state.text||'';tool.sources=data.state.sources||[];tool.settings=Object.assign(tool.settings,data.state.settings||{});tool.meta=data.state.meta||{};loadSources();syncText(true);saveSettings();toast('备份已恢复，请点击保存订阅','success')}catch(error){toast('恢复失败: '+error.message,'error')}}
async function deleteBackup(){var select=el('chainToolBackupSelect'),id=select&&select.value;if(!id){toast('请先选择备份','error');return}if(!confirm('确认删除所选备份？'))return;try{var response=await fetch('/admin/chain/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'delete',id:id})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'删除失败');await loadBackups();loadAudit();toast('备份已删除','success')}catch(error){toast('删除备份失败: '+error.message,'error')}}
function hostToIp(host){var clean=String(host||'').replace(/^\[|\]$/g,'');if(/^(?:\d{1,3}\.){3}\d{1,3}$/.test(clean)||clean.indexOf(':')>=0)return Promise.resolve(clean);return fetch('https://dns.google/resolve?name='+encodeURIComponent(clean)+'&type=A',{cache:'no-store'}).then(function(r){if(!r.ok)throw new Error('DNS HTTP '+r.status);return r.json()}).then(function(data){var answer=(data.Answer||[]).find(function(x){return x.type===1&&x.data});if(!answer)throw new Error('域名没有 A 记录');return answer.data})}
function normalizeType(value){var text=String(value||'').toLowerCase().trim().replace(/[_-]+/g,' ');if(!text)return'';if(/^(isp|res|residential|mobile|cellular|home|broadband)$/.test(text)||/residential|mobile|cellular|broadband|home isp|住宅|家宽/.test(text))return'isp';if(/^(hosting|host|datacenter|data center|cloud|vps|server)$/.test(text)||/hosting|datacenter|data center|cloud|vps|server|机房/.test(text))return'hosting';if(/^(business|commercial|enterprise)$/.test(text)||/business|commercial|enterprise|商用/.test(text))return'business';return text}
function normalizeIpInfo(info,ip,landingIp,source,extra){var data=info&&typeof info==='object'?info:{},location=data.location&&typeof data.location==='object'?data.location:{},company=data.company&&typeof data.company==='object'?data.company:{},asn=data.asn&&typeof data.asn==='object'?data.asn:{},residentialFlag=!!(data.is_residential||data.residential||data.isResidential||data.is_home||data.home),type=normalizeType(company.type||asn.type||data.company_type||data.asn_type||data.companyType||data.asnType||data.proxy_type||data.ip_type||data.network_type||data.category||data.type),mobile=!!(data.is_mobile||data.mobile||data.isMobile||company.mobile||asn.mobile);if(!type&&(mobile||residentialFlag))type='isp';var country=String(location.country_code||location.countryCode||data.country_code||data.cc||data.country||'').trim().toUpperCase(),asnName=String(asn.org||asn.organization||data.asn_organization||data.asn_org||data.organization||data.as_name||company.name||'').trim(),asnValue=String(asn.asn||data.asn||data.asn_num||'').trim(),result={type:type,ip:String(data.ip||ip||''),landingIp:String(landingIp||ip||''),country:country,asn:asnValue,organization:asnName,mobile:mobile,residential:residentialFlag,status:'info',source:String(source||''),checkedAt:new Date().toISOString()};if(extra&&extra.latency)result.latency=extra.latency;if(extra&&extra.country&&!result.country)result.country=String(extra.country).trim().toUpperCase();return result}
function hasKnownType(info){return!!(info&&(info.type==='isp'||info.type==='hosting'||info.type==='business'||info.mobile||info.residential))}
function infoScore(info){return(hasKnownType(info)?6:0)+(info&&info.country?2:0)+(info&&info.organization?1:0)}
function requestJson(url){var controller=typeof AbortController==='function'?new AbortController():null,timer=controller?setTimeout(function(){controller.abort()},6500):null,options={cache:'no-store'};if(controller)options.signal=controller.signal;return fetch(url,options).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.json()}).finally(function(){if(timer)clearTimeout(timer)})}
async function fetchNormalizedIpInfo(ip){var candidates=[{source:'ipapi',url:'https://api.090227.xyz/api/ipapi?ip='+encodeURIComponent(ip)},{source:'ipapi.is',url:'https://api.ipapi.is/?q='+encodeURIComponent(ip)}],best=null,lastError=null;for(var i=0;i<candidates.length;i++){try{var payload=await requestJson(candidates[i].url);if(typeof window.normalizeIpapiData==='function')payload=window.normalizeIpapiData(payload);var normalized=normalizeIpInfo(payload,ip,ip,candidates[i].source);if(!best||infoScore(normalized)>infoScore(best))best=normalized;if(hasKnownType(normalized))return normalized}catch(error){lastError=error}}if(typeof window.fetchIpInfoByIp==='function'){try{var fallback=await window.fetchIpInfoByIp(ip),normalizedFallback=normalizeIpInfo(fallback,ip,ip,'ipsb');if(!best||infoScore(normalizedFallback)>infoScore(best))best=normalizedFallback;if(hasKnownType(normalizedFallback)||normalizedFallback.country||normalizedFallback.organization)return normalizedFallback}catch(error){lastError=error}}if(best)return best;throw lastError||new Error('IP 信息接口无返回')}
async function resolveLanding(item){if(item.chain&&item.chainProtocol&&item.chainAddress){var query=new URLSearchParams();query.set(item.chainProtocol,item.chainAddress);var response=await fetch('/admin/check?'+query.toString()+'&_t='+Date.now(),{cache:'no-store'}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'链式落地检测失败');return{ip:String(data.ip||'').trim(),country:String(data.loc||'').trim(),latency:Number(data.responseTime)||null}}return{ip:await hostToIp(item.host),country:'',latency:null}}
async function inspectOne(item){var landing=await resolveLanding(item);if(!landing.ip)throw new Error('未取得落地 IP');var info=await fetchNormalizedIpInfo(landing.ip);return Object.assign(info,{ip:landing.ip,landingIp:landing.ip,country:landing.country||info.country,latency:landing.latency||info.latency||null})}
async function inspectIndexes(indexes,openDetail){var items=indexes.map(function(i){return parseLine(tool.lines[i],i)}).filter(function(x){return x.kind==='entry'});if(!items.length){toast('没有可检测的节点','error');return}var button=el('chainToolInspect');if(button)button.disabled=true;var cursor=0,detailMeta=null,worker=async function(){while(cursor<items.length){var item=items[cursor++],key=keyFor(item);tool.meta[key]={status:'pending',checkedAt:new Date().toISOString()};render();try{var result=await inspectOne(item);tool.meta[key]=result;if(openDetail&&!detailMeta)detailMeta=result}catch(error){tool.meta[key]={type:'',status:'error',organization:error.message,checkedAt:new Date().toISOString()}}render()}};try{await Promise.all(Array.from({length:Math.min(4,items.length)},worker));persistLocal();if(openDetail&&detailMeta&&detailMeta.landingIp&&typeof window.showIpDetailForProxy==='function')window.showIpDetailForProxy(detailMeta.landingIp);toast('IP 类型检测完成','success')}finally{if(button)button.disabled=false}}
async function probeSelected(){var indexes=selectedIndexes(),entries=indexes.map(function(i){var item=parseLine(tool.lines[i],i);return item.kind==='entry'?{endpoint:item.endpoint,index:i}:null}).filter(Boolean).slice(0,10);if(!tool.networkToolsEnabled){toast('节点测速需要部署变量 CHAIN_NETWORK_TOOLS=1','info');return}if(!entries.length){toast('请先选择要测速的节点','error');return}var button=el('chainToolProbe');if(button)button.disabled=true;try{var response=await fetch('/admin/chain/probe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entries:entries})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'测速失败');data.results.forEach(function(result){var resultEndpoint=String(result.endpoint||'').toLowerCase(),item=Number.isInteger(result.index)?entries.find(function(x){return x.index===result.index}):null;if(!item)item=entries.find(function(x){return x.endpoint.toLowerCase()===resultEndpoint||x.endpoint.toLowerCase()+':443'===resultEndpoint});if(!item)return;var key=keyFor(parseLine(tool.lines[item.index],item.index)),old=tool.meta[key]||{};tool.meta[key]=Object.assign({},old,{status:result.success?'up':'down',latency:result.responseTime,probeStatus:result.status,probeError:result.error||'',checkedAt:new Date().toISOString()})});persistLocal();render();toast('测速完成','success')}catch(error){toast('测速失败: '+error.message,'error')}finally{if(button)button.disabled=!tool.networkToolsEnabled}}
